(D/"request.json").write_text(json.dumps(r,ensure_ascii=False,indent=2),encoding="utf-8");(D/"prompt.txt").write_text(prompt,encoding="utf-8")
p["references"]=[{"file":f,"sha256":hashlib.sha256(Path(f).read_bytes()).hexdigest()} for f in refs];(D/"preparation.json").write_text(json.dumps(p,ensure_ascii=False,indent=2),encoding="utf-8")
print(json.dumps(r["payload"]))

